Under isochoric (constant volume) conditions, the heat energy (dQ) supplied to an ideal gas contributes solely to the change in its internal energy (dU).
Mathematically, this can be expressed as
$$
\begin{aligned}
& \mathrm{dQ}=\mathrm{dU}+\mathrm{dW} \\
& \Rightarrow \mathrm{dQ}=\mathrm{dU}
\end{aligned}
$$

As the change is sudden, the process is adiabatic
$\begin{array}{ll}
\therefore & \mathrm{P}_1 \mathrm{~V}_1^\gamma=\mathrm{P}_2 \mathrm{~V}_2^\gamma \\
\therefore & \frac{\mathrm{P}_2}{\mathrm{P}_1}=\left[\frac{\mathrm{V}_1}{\mathrm{~V}_2}\right]^\gamma=\left[\frac{4}{1}\right]^{3 / 2}=\frac{8}{1}
\end{array}$

Here, $\mathrm{V}_1=\mathrm{V}$ cc, $\mathrm{V}_2=\frac{\mathrm{v}}{4} \mathrm{cc}, \mathrm{Y}=\frac{5}{2}, \mathrm{P}_1=\mathrm{P}$
for adiabatic change,
$\begin{aligned} & \mathrm{P}_2 \mathrm{~V}_2=\mathrm{P}_1 \mathrm{~V}_1^{\mathrm{Y}} \\ & \therefore \mathrm{P}_1=\mathrm{P}\left\{\frac{\mathrm{V}}{\left(\frac{\mathrm{V}}{4}\right)}\right\}^Y \\ & \mathrm{P}_2=\mathrm{P}(4)^{5 / 2}=\mathrm{P}\left(2^5\right)=32 \mathrm{P}\end{aligned}$

$$
\frac{C_p}{C_v}=\frac{3}{2}
$$
Case I:
Isothermal process
$$
\begin{aligned}
& \mathrm{P}_1 \mathrm{~V}_1=\mathrm{P}_2 \mathrm{~V}_2 \\
& \mathrm{PV}=\mathrm{P}_2 \times 9 \mathrm{~V} \\
& \therefore \mathrm{P}_2=\frac{\mathrm{P}}{9}
\end{aligned}
$$
Case II: Adiabatic process
$$
\begin{aligned}
& \mathrm{P}_2 \mathrm{~V}_2^\gamma=\mathrm{P}_3 \mathrm{~V}_3^\gamma \\
& \frac{\mathrm{P}}{9}(9 \mathrm{~V})^\gamma=\mathrm{P}_3(\mathrm{~V})^\gamma \\
& \mathrm{P}_3=\left(\frac{\mathrm{P}}{9}\right) 9^\gamma=\left(\frac{\mathrm{P}}{9}\right) 9^{3 / 2}=\frac{\mathrm{P}}{9} \times 27=3 \mathrm{P}
\end{aligned}
$$

At constant pressure, $\mathrm{W}=\mathrm{P} . \Delta \mathrm{V}$
For an ideal gas, $\mathrm{PV}=\mathrm{nRT}$
$$
\begin{aligned}
& \therefore \mathrm{P} \Delta \mathrm{V}=\mathrm{n} \mathrm{R} \Delta \mathrm{T} \\
& \mathrm{W}=\mathrm{n} \mathrm{R} \Delta \mathrm{T}
\end{aligned}
$$
Heat supplied at constant volume,
$$
\begin{aligned}
& \mathrm{Q}=\Delta \mathrm{U}=\mathrm{nC}_{\mathrm{v}} \Delta \mathrm{T}=\mathrm{n} \frac{3 \mathrm{R}}{2} \Delta \mathrm{T} \\
& \quad\left(\text { Formonoatomic gas } \mathrm{C}_{\mathrm{v}}=\frac{3}{2} \mathrm{R}\right) \\
& \therefore \mathrm{Q}=\frac{3 \mathrm{~W}}{2}
\end{aligned}
$$

For isothermal expansion we have
$$
\begin{aligned}
& \mathrm{P}_1 \mathrm{~V}_1=\mathrm{P}_2 \mathrm{~V}_2 \\
& \therefore \mathrm{P}_2=\mathrm{P}_1 \frac{\mathrm{V}_1}{\mathrm{~V}_2}=\mathrm{P}_1 \times \frac{1}{2}=\frac{\mathrm{P}}{2} \\
& \therefore \mathrm{P}_{\mathrm{i}}=\frac{\mathrm{P}}{2}
\end{aligned}
$$
For adiabatic process:
$$
\begin{aligned}
& \mathrm{P}_1 \mathrm{~V}_1^\gamma=\mathrm{P}_2 \mathrm{~V}_2^\gamma \\
& \therefore \mathrm{P}_2=\mathrm{P}_1\left(\frac{\mathrm{V}_1}{\mathrm{~V}_2}\right)^\gamma=\mathrm{P}_1\left(\frac{1}{2}\right)^\gamma=\frac{\mathrm{P}}{2^\gamma} \\
& \therefore \mathrm{P}_{\mathrm{a}}=\frac{\mathrm{P}}{2^\gamma} \\
& \therefore \frac{\mathrm{P}_{\mathrm{i}}}{\mathrm{P}_{\mathrm{a}}}=\frac{2^\gamma}{2}=2^{\gamma-1}
\end{aligned}
$$

For an adiabatic process $\mathrm{TV}^{\gamma-1}=$ constant
$$
\begin{aligned}
& \therefore \frac{\mathrm{T}_2}{\mathrm{~T}_1}=\left(\frac{\mathrm{V}_1}{\mathrm{~V}_2}\right)^{\gamma-1}=\left(\frac{27}{8}\right)^{\frac{5}{3}-1}=\left(\frac{27}{8}\right)^{\frac{2}{3}}=\frac{9}{4} \\
& \therefore \mathrm{T}_2=\frac{9}{4} \cdot \mathrm{T}_1=\frac{9}{4} \times 300=675 \mathrm{~K} \\
& \therefore \mathrm{T}_2-\mathrm{T}_1=675-300=375 \mathrm{~K}
\end{aligned}
$$

$$
\begin{aligned}
& \gamma=\frac{\mathrm{C}_{\mathrm{p}}}{\mathrm{C}_{\mathrm{v}}} \text { and } \mathrm{C}_{\mathrm{p}}-\mathrm{C}_{\mathrm{v}}=\mathrm{R} \\
& \mathrm{C}_{\mathrm{p}}=\gamma \mathrm{C}_{\mathrm{v}} \\
& \therefore \gamma \mathrm{C}_{\mathrm{v}}-\mathrm{C}_{\mathrm{v}}=\mathrm{R} \\
& \text { Or, } \mathrm{C}_{\mathrm{v}}=\frac{\mathrm{R}}{\gamma-1}
\end{aligned}
$$

For isothermal process: $\mathrm{P}_1 \mathrm{~V}_1=\mathrm{P}_2 \mathrm{~V}_2$
$$
\therefore \mathrm{P}_2=\frac{\mathrm{P}_1 \mathrm{~V}_1}{\mathrm{~V}_2}=\frac{\mathrm{P}_1}{2}
$$
For adiabatic process: $\mathrm{P}_2 \mathrm{~V}_2^\gamma=\mathrm{P}_3 \mathrm{~V}_3^\gamma$
$$
\begin{aligned}
& \therefore \mathrm{P}_3=\mathrm{P}_2\left(\frac{\mathrm{V}_2}{\mathrm{~V}_3}\right)^\gamma=\mathrm{P}_2\left(\frac{2 \mathrm{~V}}{16 \mathrm{~V}}\right)^\gamma=\frac{\mathrm{P}_1}{2}\left(\frac{1}{8}\right)^{5 / 3} \\
& =\frac{\mathrm{P}}{2} \times \frac{1}{32}=\frac{\mathrm{P}}{64}
\end{aligned}
$$

$$
\begin{aligned}
& \gamma=\frac{C_p}{C_v} \text { and } C_p-C_v=R \\
& C_p=\gamma C_v \\
& \therefore \gamma C_v-C_v=R \\
& \text { Or, } C_v=\frac{R}{\gamma-1}
\end{aligned}
$$

Heat supplied at constant pressure, $\mathrm{Q}_1=\mathrm{nC}_{\mathrm{p}} \Delta \mathrm{T}$ Heat supplied at constant volume, $\mathrm{Q}_2=\mathrm{nC}_{\mathrm{v}} \Delta \mathrm{T}$ Work done, $\mathrm{W}=\mathrm{Q}_1-\mathrm{Q}_2=\mathrm{n}\left(\mathrm{C}_{\mathrm{p}}-\mathrm{C}_{\mathrm{v}}\right) \mathrm{dT}$
$$
\begin{aligned}
& \frac{\mathrm{W}}{\mathrm{Q}_2}=\frac{\mathrm{C}_{\mathrm{p}}-\mathrm{C}_{\mathrm{v}}}{\mathrm{C}_{\mathrm{v}}}=\frac{\mathrm{C}_{\mathrm{p}}}{\mathrm{C}_{\mathrm{v}}}-1=\frac{5}{3}-1=\frac{2}{3} \\
& \mathrm{Q}_2=\frac{3 \mathrm{~W}}{2}
\end{aligned}
$$

$$
\frac{\mathrm{V}_2}{\mathrm{~V}_1}=\frac{1}{8}, \gamma=\frac{5}{3}
$$
For adiabatic process,
$$
\begin{aligned}
& \mathrm{P}_1 \mathrm{~V}_1^\gamma=\mathrm{P}_2 \mathrm{~V}_2^\gamma \\
& \therefore \frac{\mathrm{P}_2}{\mathrm{P}_1}=\left(\frac{\mathrm{V}_1}{\mathrm{~V}_2}\right)^\gamma=(8)^{5 / 3}=(2)^5=32
\end{aligned}
$$

Given, $\mathrm{PV}^{3 / 2}=$ constant or $\mathrm{TV}^{1 / 2}=$ constant
$$
\begin{aligned}
& \therefore \mathrm{T}_1 \mathrm{~V}_1^{1 / 2}=\mathrm{T}_2 \mathrm{~V}_2^{1 / 2} \\
& \frac{\mathrm{T}_2}{\mathrm{~T}_1}=\left(\frac{\mathrm{V}_1}{\mathrm{~V}_2}\right)^{1 / 2}=\sqrt{2} \\
& \mathrm{~T}_2=\sqrt{2} \mathrm{~T}_1=\sqrt{2} \mathrm{~T}
\end{aligned}
$$

Ideal gas equation
$$
\begin{array}{c}
p V=n R T \\
\frac{p V}{T}=n R=\frac{m}{M} R \\
\frac{m}{M} R=\frac{10 \times V}{300} \\
\frac{m}{2 M} R=\frac{p V}{360}
\end{array}
$$
$$
\begin{aligned}
\frac{p V}{360} &=\frac{1}{2} \frac{10 \mathrm{~V}}{300} \\
p &=\frac{3600}{2 \times 300}=6 \mathrm{~atm}
\end{aligned}
$$
